def pose_rule(p):
    r = RULE.get(p["id"], dict(met=2.6, work=5, pat="pushing"))
    ct = {"hand-skin": {"fraction": 0.35, "tempC": 8}, "tyres": {"fraction": 0.003, "tempC": 8}}
    n = sum(1 for s in "lr" if any(x in p["contacts"] for x in (f"heel-{s}", f"contact-{s}")))
    if n: ct["shoes"] = {"fraction": round(0.175*n, 3), "tempC": 8}
    return {"met": r["met"], "work": r["work"], "pat": r["pat"], "contact": ct, "ex": r.get("ex", {}), "em": {"plume": 0.6 if r["met"] < 2 else 0.8}}
